import { readdirSync } from "node:fs";
import { describe, expect, it } from "vitest";

// Each package directory has a hand-written index.ts that must re-export the
// code generated by protoc-gen-es.
describe("package indexes", () => {
  const packages = readdirSync(new URL(".", import.meta.url), {
    withFileTypes: true,
  })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)
    .filter((name) =>
      readdirSync(new URL(`./${name}/`, import.meta.url)).includes("index.ts"),
    );

  it("finds the packages", () => {
    expect(packages).toEqual([
      "envelopepb",
      "identitypb",
      "messaginggrpc",
      "uuidpb",
    ]);
  });

  describe.each(packages)("%s", (pkg) => {
    const generated = readdirSync(new URL(`./${pkg}/`, import.meta.url))
      .filter((f) => f.endsWith("_pb.ts"))
      .map((f) => f.slice(0, -".ts".length));

    it.each(generated)("re-exports %s", async (name) => {
      // The paths are only known at runtime, so they're imported by URL rather
      // than letting Vite rewrite the import with a list of files that it
      // found, which it caches.
      const index = await import(
        /* @vite-ignore */ new URL(`./${pkg}/index.ts`, import.meta.url).href
      );
      const module = await import(
        /* @vite-ignore */ new URL(`./${pkg}/${name}.ts`, import.meta.url).href
      );

      for (const [key, value] of Object.entries(module)) {
        expect(index, key).toHaveProperty(key, value);
      }
    });
  });
});
